package com.ruoyi.web.biz;
import java.util.*;
import java.math.BigDecimal;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
@Service
public class TaskService {
 final JdbcTemplate db; final EmployeeService users;
 static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
 public TaskService(CompanyOnboardingMapper mapper,EmployeeService users){db=mapper.database();this.users=users;}
 LocalDateTime time(Object value){return value instanceof LocalDateTime?(LocalDateTime)value:((java.sql.Timestamp)value).toLocalDateTime();}
 Map<String,Object> publicTask(Map<String,Object> value){Map<String,Object> result=new LinkedHashMap<>(value);for(String key:List.of("publisher_id","create_by","update_by","project_id","remark","version"))result.remove(key);return result;}
 long uid(){return SecurityUtils.getUserId();}
 boolean platform(){return uid()==1||users.hasRole(uid(),"platform_admin");}
 void perm(String op){if(!users.hasPermission("biz:tasks:"+op))throw new AccessDeniedException("没有任务操作权限");}
 long enterprise(String op){perm(op);Long c=users.userCompany(uid());if(c==null||!users.hasRole(uid(),"company_admin")&&!users.hasRole(uid(),"company_business"))throw new AccessDeniedException("需有效企业管理员或企业业务角色");return c;}
 void reviewer(){perm("review");if(!platform())throw new AccessDeniedException("仅平台可审核");}
 Map<String,Object> task(long id,boolean lock){var rows=db.queryForList("SELECT * FROM biz_task WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw new ServiceException("任务不存在",404);return rows.get(0);}
 void owner(Map<String,Object> t){perm("manage");if("PLATFORM".equals(t.get("publisher_type"))){if(!platform())throw new AccessDeniedException("不能修改平台任务");}else if(platform()||enterprise("manage")!=((Number)t.get("company_id")).longValue())throw new AccessDeniedException("只能管理本企业发布任务");}
 void visible(Map<String,Object> t){perm("read");if(platform())return;long c=enterprise("read");if(t.get("company_id")!=null&&c==((Number)t.get("company_id")).longValue())return;if("PLATFORM".equals(t.get("publisher_type"))&&"SHARED".equals(t.get("audience"))&&Set.of("PUBLISHED","CLOSED").contains(t.get("status")))return;throw new ServiceException("任务不存在或无权查看",404);}
 void text(String value,int max,String name){if(value==null||value.isBlank()||value.length()>max)throw new ServiceException(name+"必填或长度无效",400);}
 void amount(BigDecimal value){if(value==null||value.signum()<=0||value.scale()>2||value.compareTo(new BigDecimal("9999999999999999.99"))>0)throw new ServiceException("工作量须为正数且最多两位小数",400);}
 void valid(TaskInput in){text(in.title(),150,"任务名称");text(in.unit(),20,"单位");if(in.description()!=null&&in.description().length()>10000)throw new ServiceException("任务描述过长",400);amount(in.targetQuantity());if(in.maxCompanies()==null||in.maxCompanies()<1||in.maxCompanies()>10000||!Set.of("SHARED","INTERNAL").contains(in.audience()==null?"":in.audience())||in.signupDeadline()==null||in.startDate()==null||in.endDate()==null||in.endDate().isBefore(in.startDate())||in.signupDeadline().isAfter(in.startDate().atTime(23,59,59)))throw new ServiceException("容量、日期或可见范围无效",400);if("INTERNAL".equals(in.audience())&&in.maxCompanies()!=1)throw new ServiceException("内部任务容量须为1家企业",400);}
 void event(long task,Long signup,Long company,String action,String opinion){db.update("INSERT INTO biz_task_event(task_id,signup_id,company_id,action,actor_id,opinion) VALUES(?,?,?,?,?,?)",task,signup,company,action,uid(),opinion);}
 Map<String,Object> capacity(long task){var rows=db.queryForList("SELECT promised_quantity FROM biz_task_signup WHERE task_id=? AND status='APPROVED' FOR UPDATE",task);BigDecimal total=BigDecimal.ZERO;for(var row:rows)total=total.add((BigDecimal)row.get("promised_quantity"));return Map.of("approved_companies",rows.size(),"approved_quantity",total);}
 void available(Map<String,Object> t){if(!"PUBLISHED".equals(t.get("status"))||!time(t.get("signup_deadline")).isAfter(LocalDateTime.now(ZONE)))throw new ServiceException("任务已关闭或超过报名截止时间",409);}
 void space(Map<String,Object> t,BigDecimal requested){var used=capacity(((Number)t.get("id")).longValue());if(((Number)used.get("approved_companies")).intValue()>=((Number)t.get("max_companies")).intValue()||((BigDecimal)used.get("approved_quantity")).add(requested).compareTo((BigDecimal)t.get("target_quantity"))>0)throw new ServiceException("企业容量或剩余工作量不足",409);}
 @Transactional public long save(Long id,TaskInput in){perm("manage");valid(in);Long company=platform()?null:enterprise("manage");if(!platform()&&!"INTERNAL".equals(in.audience()))throw new ServiceException("企业任务仅限本企业内部使用",400);if(platform()&&!"SHARED".equals(in.audience()))throw new ServiceException("平台任务须为共享任务",400);
 if(id==null){String code="TASK-"+UUID.randomUUID().toString();db.update("INSERT INTO biz_task(company_id,task_code,title,publisher_type,description,target_quantity,unit,signup_deadline,start_date,end_date,max_companies,audience,publisher_id,status,create_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'DRAFT',?)",company,code,in.title(),company==null?"PLATFORM":"COMPANY",in.description()==null?"":in.description(),in.targetQuantity(),in.unit(),in.signupDeadline(),in.startDate(),in.endDate(),in.maxCompanies(),in.audience(),uid(),SecurityUtils.getUsername());long task=db.queryForObject("SELECT id FROM biz_task WHERE task_code=?",Long.class,code);event(task,null,company,"CREATE","任务草稿创建");return task;}
 var t=task(id,true);owner(t);if(!"DRAFT".equals(t.get("status"))||in.version()==null||db.update("UPDATE biz_task SET title=?,description=?,target_quantity=?,unit=?,signup_deadline=?,start_date=?,end_date=?,max_companies=?,audience=?,version=version+1,update_by=? WHERE id=? AND version=?",in.title(),in.description()==null?"":in.description(),in.targetQuantity(),in.unit(),in.signupDeadline(),in.startDate(),in.endDate(),in.maxCompanies(),in.audience(),SecurityUtils.getUsername(),id,in.version())!=1)throw new ServiceException("任务状态或版本已变化，仅草稿可编辑",409);if(!in.unit().equals(t.get("unit"))&&t.get("unit_price")!=null){db.update("UPDATE biz_task SET unit_price=NULL,price_version=price_version+1 WHERE id=?",id);db.update("INSERT INTO biz_task_price_audit(task_id,company_id,old_price,new_price,price_version,opinion,actor_id) VALUES(?,?,?,NULL,?,'任务单位变更，原报价作废',?)",id,t.get("company_id"),t.get("unit_price"),((Number)t.get("price_version")).intValue()+1,uid());}event(id,null,company,"EDIT","任务草稿修改");return id;}
 @Transactional public void publish(long id,Integer version){var t=task(id,true);owner(t);if(!"DRAFT".equals(t.get("status"))||version==null||version.intValue()!=((Number)t.get("version")).intValue())throw new ServiceException("任务状态或版本已变化",409);if(t.get("signup_deadline")==null||!time(t.get("signup_deadline")).isAfter(LocalDateTime.now(ZONE)))throw new ServiceException("报名截止时间须晚于当前时间",400);if(((BigDecimal)t.get("target_quantity")).signum()<=0)throw new ServiceException("目标量须大于0",400);db.update("UPDATE biz_task SET status='PUBLISHED',version=version+1,update_by=? WHERE id=?",SecurityUtils.getUsername(),id);event(id,null,(Long)t.get("company_id"),"PUBLISH","任务发布");}
 @Transactional public void close(long id,Integer version,String reason){var t=task(id,true);owner(t);text(reason,500,"关闭原因");if(!"PUBLISHED".equals(t.get("status"))||version==null||version.intValue()!=((Number)t.get("version")).intValue())throw new ServiceException("任务状态或版本已变化",409);db.update("UPDATE biz_task SET status='CLOSED',close_reason=?,version=version+1,update_by=? WHERE id=?",reason,SecurityUtils.getUsername(),id);event(id,null,(Long)t.get("company_id"),"CLOSE",reason);}
 public Map<String,Object> list(boolean mine,int page,int size,String keyword){perm(mine?"manage":"read");if(page<1||page>100000||size<1||size>100||keyword!=null&&keyword.length()>100)throw new ServiceException("查询参数无效",400);List<Object> args=new ArrayList<>();String where;if(mine){if(platform())where="t.publisher_type='PLATFORM'";else{where="t.company_id=?";args.add(enterprise("manage"));}}else{where="t.status='PUBLISHED' AND t.signup_deadline>CURRENT_TIMESTAMP AND (SELECT COUNT(*) FROM biz_task_signup s WHERE s.task_id=t.id AND s.status='APPROVED')<t.max_companies AND (SELECT COALESCE(SUM(s.promised_quantity),0) FROM biz_task_signup s WHERE s.task_id=t.id AND s.status='APPROVED')<t.target_quantity";if(!platform()){long c=enterprise("read");where+=" AND ((t.publisher_type='PLATFORM' AND t.audience='SHARED') OR (t.publisher_type='COMPANY' AND t.audience='INTERNAL' AND t.company_id=?))";args.add(c);}}
 if(keyword!=null&&!keyword.isBlank()){where+=" AND t.title LIKE ?";args.add("%"+keyword+"%");}long total=db.queryForObject("SELECT COUNT(*) FROM biz_task t WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);var rows=db.queryForList("SELECT t.*,(SELECT COUNT(*) FROM biz_task_signup s WHERE s.task_id=t.id AND s.status='APPROVED') AS approved_companies FROM biz_task t WHERE "+where+" ORDER BY t.id DESC LIMIT ? OFFSET ?",args.toArray());if(!mine&&!platform()){List<Map<String,Object>> safe=new ArrayList<>();for(var row:rows)safe.add(publicTask(row));return Map.of("rows",safe,"total",total);}return Map.of("rows",rows,"total",total);}
 public Map<String,Object> detail(long id){var t=task(id,false);visible(t);t.putAll(capacity(id));if(!platform()&&(t.get("company_id")==null||!users.userCompany(uid()).equals(t.get("company_id"))))return publicTask(t);return t;}
 Map<String,Object> signup(long id,boolean lock){var rows=db.queryForList("SELECT * FROM biz_task_signup WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw new ServiceException("报名不存在",404);return rows.get(0);}
 @Transactional public long apply(long id,BigDecimal quantity){long company=enterprise("signup");amount(quantity);var t=task(id,true);available(t);if("COMPANY".equals(t.get("publisher_type"))&&(t.get("company_id")==null||company!=((Number)t.get("company_id")).longValue()||!"INTERNAL".equals(t.get("audience"))))throw new AccessDeniedException("企业任务仅限本企业内部使用");if("SHARED".equals(t.get("audience"))&&t.get("company_id")!=null&&company==((Number)t.get("company_id")).longValue())throw new ServiceException("不能报名自己发布的共享任务",409);if("INTERNAL".equals(t.get("audience"))&&(t.get("company_id")==null||company!=((Number)t.get("company_id")).longValue()))throw new AccessDeniedException("非本企业内部任务");if(db.queryForObject("SELECT COUNT(*) FROM biz_employee_info WHERE company_id=? AND user_id=? AND status='ACTIVE'",Long.class,company,uid())!=1)throw new AccessDeniedException("缺少有效员工档案");space(t,quantity);String state="INTERNAL".equals(t.get("audience"))?"APPROVED":"PENDING";var old=db.queryForList("SELECT * FROM biz_task_signup WHERE task_id=? AND company_id=? FOR UPDATE",id,company);long sid;
 if(old.isEmpty()){db.update("INSERT INTO biz_task_signup(task_id,company_id,contact_user_id,promised_quantity,status,create_by) VALUES(?,?,?,?,?,?)",id,company,uid(),quantity,state,SecurityUtils.getUsername());sid=db.queryForObject("SELECT id FROM biz_task_signup WHERE task_id=? AND company_id=?",Long.class,id,company);}else{var a=old.get(0);if(!Set.of("REJECTED","WITHDRAWN").contains(a.get("status")))throw new ServiceException("该企业已报名，不可重复提交",409);sid=((Number)a.get("id")).longValue();db.update("UPDATE biz_task_signup SET status=?,contact_user_id=?,promised_quantity=?,round_no=round_no+1,version=version+1,update_by=? WHERE id=?",state,uid(),quantity,SecurityUtils.getUsername(),sid);}
 event(id,sid,company,state.equals("APPROVED")?"INTERNAL_ACCEPT":"SIGNUP",state.equals("APPROVED")?"本企业内部任务承接，无需平台审核；承诺工作量"+quantity:"企业提交报名，承诺工作量"+quantity);return sid;}
 @Transactional public void withdraw(long id,Integer version){long company=enterprise("signup");var base=signup(id,false);long taskId=((Number)base.get("task_id")).longValue();task(taskId,true);var a=signup(id,true);if(company!=((Number)a.get("company_id")).longValue())throw new AccessDeniedException("不能取消其他企业报名");if(!"PENDING".equals(a.get("status"))||version==null||version.intValue()!=((Number)a.get("version")).intValue())throw new ServiceException("仅待审核报名可取消或版本冲突",409);db.update("UPDATE biz_task_signup SET status='WITHDRAWN',version=version+1,update_by=? WHERE id=?",SecurityUtils.getUsername(),id);event(taskId,id,company,"WITHDRAW","企业撤回待审核报名");}
 @Transactional public void review(long id,boolean approve,String opinion,Integer version){reviewer();text(opinion,500,"审核意见");var base=signup(id,false);long taskId=((Number)base.get("task_id")).longValue();var t=task(taskId,true);var a=signup(id,true);if(!"PENDING".equals(a.get("status"))||version==null||version.intValue()!=((Number)a.get("version")).intValue())throw new ServiceException("报名状态或版本已变化",409);long applicant=((Number)a.get("contact_user_id")).longValue(),company=((Number)a.get("company_id")).longValue();if(applicant==uid())throw new AccessDeniedException("不得审核本人报名");if(approve){if("COMPANY".equals(t.get("publisher_type"))&&(t.get("company_id")==null||company!=((Number)t.get("company_id")).longValue()))throw new AccessDeniedException("不能通过其他企业的内部任务报名");if(!"PUBLISHED".equals(t.get("status")))throw new ServiceException("任务已关闭，不能通过报名",409);if(db.queryForObject("SELECT COUNT(*) FROM biz_company WHERE id=? AND status='ACTIVE'",Long.class,company)!=1||db.queryForObject("SELECT COUNT(*) FROM biz_company_user WHERE user_id=? AND company_id=? AND status='ACTIVE'",Long.class,applicant,company)!=1)throw new ServiceException("企业或报名联系人归属无效",409);space(t,(BigDecimal)a.get("promised_quantity"));}
 String state=approve?"APPROVED":"REJECTED";db.update("UPDATE biz_task_signup SET status=?,version=version+1,update_by=? WHERE id=?",state,SecurityUtils.getUsername(),id);db.update("INSERT INTO biz_audit_record(company_id,business_type,business_id,round_no,applicant_id,reviewer_id,from_status,to_status,opinion,status) VALUES(?,'task_signup',?,?,?,?,'PENDING',?,?,'RECORDED')",company,id,a.get("round_no"),applicant,uid(),state,opinion);event(taskId,id,company,state,opinion);}
 public Map<String,Object> signups(boolean review,int page,int size){if(review)reviewer();else enterprise("signup");if(page<1||page>100000||size<1||size>100)throw new ServiceException("分页无效",400);String where=review?"1=1":"s.company_id=?";List<Object> args=new ArrayList<>();if(!review)args.add(enterprise("signup"));long total=db.queryForObject("SELECT COUNT(*) FROM biz_task_signup s WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);return Map.of("rows",db.queryForList("SELECT s.*,t.title,t.unit,t.status AS task_status,c.company_name FROM biz_task_signup s JOIN biz_task t ON t.id=s.task_id JOIN biz_company c ON c.id=s.company_id WHERE "+where+" ORDER BY s.id DESC LIMIT ? OFFSET ?",args.toArray()),"total",total);}
 public Map<String,Object> signupDetail(long id){var a=signup(id,false);if(platform())reviewer();else if(enterprise("signup")!=((Number)a.get("company_id")).longValue())throw new AccessDeniedException("无权查看其他企业报名");a.put("audits",db.queryForList("SELECT round_no,to_status,opinion,reviewed_at FROM biz_audit_record WHERE business_type='task_signup' AND business_id=? ORDER BY round_no",id));a.put("events",db.queryForList("SELECT action,opinion,create_time FROM biz_task_event WHERE signup_id=? ORDER BY id",id));a.put("readyForAssignment","APPROVED".equals(a.get("status")));return a;}
}
